        :root {
            --primary: #f0a800;
            --primary-dark: #c88a00;
            --secondary: #1a9eff;
            --dark: #0a0e1a;
            --dark-2: #0f1523;
            --dark-3: #161d2e;
            --dark-4: #1e2740;
            --text: #c8d6e5;
            --text-light: #8fa3b8;
            --white: #ffffff;
            --red: #ff4444;
            --green: #44ff88;
            --border: rgba(240, 168, 0, 0.2);
            --glow: 0 0 20px rgba(240, 168, 0, 0.3);
            --glow-blue: 0 0 20px rgba(26, 158, 255, 0.3);
        }

        html {
            scroll-behavior: smooth;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: var(--dark);
            color: var(--text);
            overflow-x: hidden;
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        ul {
            list-style: none;
        }

        img {
            max-width: 100%;
        }

        /* ===== SCROLLBAR ===== */
        ::-webkit-scrollbar {
            width: 6px;
        }

        ::-webkit-scrollbar-track {
            background: var(--dark-2);
        }

        ::-webkit-scrollbar-thumb {
            background: var(--primary);
            border-radius: 3px;
        }

        /* ===== UTILITY CLASSES ===== */
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
        }

        .btn {
            display: inline-block;
            padding: 12px 28px;
            border-radius: 4px;
            font-weight: 700;
            font-size: 14px;
            letter-spacing: 1px;
            text-transform: uppercase;
            cursor: pointer;
            transition: all 0.3s ease;
            border: none;
        }

        .btn-primary {
            background: linear-gradient(135deg, var(--primary), var(--primary-dark));
            color: var(--dark);
            box-shadow: var(--glow);
        }

        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: 0 0 30px rgba(240, 168, 0, 0.5);
        }

        .btn-secondary {
            background: transparent;
            color: var(--primary);
            border: 2px solid var(--primary);
        }

        .btn-secondary:hover {
            background: var(--primary);
            color: var(--dark);
            transform: translateY(-2px);
        }

        .btn-blue {
            background: linear-gradient(135deg, var(--secondary), #0077cc);
            color: var(--white);
            box-shadow: var(--glow-blue);
        }

        .btn-blue:hover {
            transform: translateY(-2px);
            box-shadow: 0 0 30px rgba(26, 158, 255, 0.5);
        }

        .section-title {
            font-size: 36px;
            font-weight: 900;
            text-transform: uppercase;
            letter-spacing: 2px;
            color: var(--white);
            margin-bottom: 10px;
        }

        .section-title span {
            color: var(--primary);
        }

        .section-subtitle {
            color: var(--text-light);
            font-size: 14px;
            letter-spacing: 3px;
            text-transform: uppercase;
            margin-bottom: 8px;
        }

        .section-line {
            width: 60px;
            height: 3px;
            background: linear-gradient(90deg, var(--primary), transparent);
            margin: 15px 0 40px;
        }

        .badge {
            display: inline-block;
            padding: 4px 12px;
            border-radius: 20px;
            font-size: 11px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        .badge-gold {
            background: rgba(240, 168, 0, 0.2);
            color: var(--primary);
            border: 1px solid var(--primary);
        }

        .badge-blue {
            background: rgba(26, 158, 255, 0.2);
            color: var(--secondary);
            border: 1px solid var(--secondary);
        }

        .badge-red {
            background: rgba(255, 68, 68, 0.2);
            color: var(--red);
            border: 1px solid var(--red);
        }

        .badge-green {
            background: rgba(68, 255, 136, 0.2);
            color: var(--green);
            border: 1px solid var(--green);
        }

        /* ===== LOADING SCREEN ===== */
        #loading-screen {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: var(--dark);
            z-index: 9999;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            transition: opacity 0.5s ease;
        }

        .loading-logo {
            font-size: 48px;
            font-weight: 900;
            color: var(--primary);
            letter-spacing: 5px;
            text-transform: uppercase;
            animation: pulse 1s infinite;
        }

        .loading-logo span {
            color: var(--white);
        }

        .loading-bar-container {
            width: 300px;
            height: 4px;
            background: var(--dark-4);
            border-radius: 2px;
            margin-top: 30px;
            overflow: hidden;
        }

        .loading-bar {
            height: 100%;
            background: linear-gradient(90deg, var(--primary), var(--secondary));
            border-radius: 2px;
            animation: loadingBar 2s ease forwards;
        }

        .loading-text {
            margin-top: 15px;
            font-size: 12px;
            letter-spacing: 3px;
            text-transform: uppercase;
            color: var(--text-light);
        }

        @keyframes loadingBar {
            from { width: 0%; }
            to { width: 100%; }
        }

        @keyframes pulse {
            0%, 100% { opacity: 1; }
            50% { opacity: 0.7; }
        }

        /* ===== NAVBAR ===== */
        #navbar {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            z-index: 1000;
            padding: 0 30px;
            transition: all 0.3s ease;
            background: rgba(10, 14, 26, 0.95);
            backdrop-filter: blur(10px);
            border-bottom: 1px solid var(--border);
        }

        #navbar.scrolled {
            padding: 0 30px;
            box-shadow: 0 5px 30px rgba(0, 0, 0, 0.5);
        }

        .nav-container {
            display: flex;
            align-items: center;
            justify-content: space-between;
            height: 70px;
            max-width: 1400px;
            margin: 0 auto;
        }

        .nav-logo {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .nav-logo-icon {
            width: 40px;
            height: 40px;
            background: linear-gradient(135deg, var(--primary), var(--primary-dark));
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 20px;
            color: var(--dark);
            font-weight: 900;
        }

        .nav-logo-text {
            font-size: 22px;
            font-weight: 900;
            color: var(--white);
            letter-spacing: 2px;
        }

        .nav-logo-text span {
            color: var(--primary);
        }

        .nav-links {
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .nav-links a {
            padding: 8px 16px;
            border-radius: 4px;
            font-size: 13px;
            font-weight: 600;
            letter-spacing: 1px;
            text-transform: uppercase;
            color: var(--text);
            transition: all 0.3s ease;
            position: relative;
        }

        .nav-links a::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 50%;
            transform: translateX(-50%);
            width: 0;
            height: 2px;
            background: var(--primary);
            transition: width 0.3s ease;
        }

        .nav-links a:hover {
            color: var(--primary);
        }

        .nav-links a:hover::after {
            width: 70%;
        }

        .nav-links a.active {
            color: var(--primary);
        }

        .nav-links a.active::after {
            width: 70%;
        }

        .nav-actions {
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .nav-search {
            display: flex;
            align-items: center;
            background: var(--dark-3);
            border: 1px solid var(--border);
            border-radius: 4px;
            padding: 8px 15px;
            gap: 8px;
            transition: all 0.3s ease;
        }

        .nav-search:focus-within {
            border-color: var(--primary);
            box-shadow: var(--glow);
        }

        .nav-search input {
            background: none;
            border: none;
            outline: none;
            color: var(--text);
            font-size: 13px;
            width: 160px;
        }

        .nav-search input::placeholder {
            color: var(--text-light);
        }

        .nav-search i {
            color: var(--text-light);
            font-size: 13px;
        }

        .nav-avatar {
            width: 38px;
            height: 38px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--primary), var(--secondary));
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 16px;
            color: var(--dark);
            cursor: pointer;
            transition: all 0.3s ease;
            font-weight: 700;
        }

        .nav-avatar:hover {
            transform: scale(1.1);
            box-shadow: var(--glow);
        }

        .hamburger {
            display: none;
            flex-direction: column;
            gap: 5px;
            cursor: pointer;
            padding: 5px;
        }

        .hamburger span {
            display: block;
            width: 25px;
            height: 2px;
            background: var(--primary);
            transition: all 0.3s ease;
        }

        /* ===== HERO SECTION ===== */
        #hero {
            min-height: 100vh;
            position: relative;
            display: flex;
            align-items: center;
            overflow: hidden;
            background: var(--dark);
        }

        .hero-bg {
            position: absolute;
            inset: 0;
            background: 
                radial-gradient(ellipse at 20% 50%, rgba(240, 168, 0, 0.08) 0%, transparent 50%),
                radial-gradient(ellipse at 80% 50%, rgba(26, 158, 255, 0.08) 0%, transparent 50%),
                linear-gradient(180deg, var(--dark) 0%, var(--dark-2) 100%);
        }

        .hero-grid {
            position: absolute;
            inset: 0;
            background-image: 
                linear-gradient(rgba(240, 168, 0, 0.03) 1px, transparent 1px),
                linear-gradient(90deg, rgba(240, 168, 0, 0.03) 1px, transparent 1px);
            background-size: 50px 50px;
        }

        .hero-particles {
            position: absolute;
            inset: 0;
            overflow: hidden;
        }

        .particle {
            position: absolute;
            width: 2px;
            height: 2px;
            background: var(--primary);
            border-radius: 50%;
            opacity: 0;
            animation: floatParticle linear infinite;
        }

        @keyframes floatParticle {
            0% {
                opacity: 0;
                transform: translateY(100vh) rotate(0deg);
            }
            10% { opacity: 1; }
            90% { opacity: 1; }
            100% {
                opacity: 0;
                transform: translateY(-100px) rotate(720deg);
            }
        }

        .hero-content {
            position: relative;
            z-index: 2;
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
            padding-top: 100px;
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 60px;
            align-items: center;
            width: 100%;
        }

        .hero-left {
            animation: slideInLeft 1s ease forwards;
        }

        .hero-eyebrow {
            display: flex;
            align-items: center;
            gap: 12px;
            margin-bottom: 20px;
        }

        .hero-eyebrow-line {
            width: 40px;
            height: 2px;
            background: var(--primary);
        }

        .hero-eyebrow-text {
            font-size: 12px;
            letter-spacing: 4px;
            text-transform: uppercase;
            color: var(--primary);
            font-weight: 700;
        }

        .hero-title {
            font-size: 72px;
            font-weight: 900;
            line-height: 1;
            text-transform: uppercase;
            color: var(--white);
            margin-bottom: 20px;
        }

        .hero-title .highlight {
            color: var(--primary);
            text-shadow: 0 0 40px rgba(240, 168, 0, 0.5);
        }

        .hero-title .stroke {
            -webkit-text-stroke: 2px var(--primary);
            color: transparent;
        }

        .hero-description {
            font-size: 16px;
            color: var(--text-light);
            line-height: 1.8;
            margin-bottom: 35px;
            max-width: 480px;
        }

        .hero-buttons {
            display: flex;
            gap: 15px;
            margin-bottom: 50px;
            flex-wrap: wrap;
        }

        .hero-stats {
            display: flex;
            gap: 40px;
        }

        .hero-stat {
            border-left: 2px solid var(--border);
            padding-left: 20px;
        }

        .hero-stat-number {
            font-size: 28px;
            font-weight: 900;
            color: var(--primary);
        }

        .hero-stat-label {
            font-size: 12px;
            color: var(--text-light);
            letter-spacing: 1px;
            text-transform: uppercase;
        }

        .hero-right {
            position: relative;
            animation: slideInRight 1s ease forwards;
        }

        .hero-card-main {
            background: linear-gradient(135deg, var(--dark-3), var(--dark-4));
            border: 1px solid var(--border);
            border-radius: 16px;
            padding: 30px;
            position: relative;
            overflow: hidden;
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
        }

        .hero-card-main::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            height: 2px;
            background: linear-gradient(90deg, transparent, var(--primary), transparent);
        }

        .hero-card-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 20px;
        }

        .hero-card-tag {
            font-size: 11px;
            letter-spacing: 3px;
            text-transform: uppercase;
            color: var(--primary);
            font-weight: 700;
        }

        .hero-card-live {
            display: flex;
            align-items: center;
            gap: 6px;
            font-size: 11px;
            color: var(--red);
            font-weight: 700;
        }

        .live-dot {
            width: 8px;
            height: 8px;
            background: var(--red);
            border-radius: 50%;
            animation: blink 1s infinite;
        }

        @keyframes blink {
            0%, 100% { opacity: 1; }
            50% { opacity: 0; }
